-- ----------------------------
-- Table structure for MONEYBAG_COURSE
-- ----------------------------
DROP TABLE IF EXISTS `MONEYBAG_COURSE`;
CREATE TABLE `MONEYBAG_COURSE`  (
  `ID_` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '课程ID',
  `TEACHER_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '教师ID',
  `NAME_` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '课程名称',
  `TOTAL_HOURS_` int NOT NULL COMMENT '预计总课时',
  `HOURS_PER_CLASS` int NOT NULL DEFAULT 45 COMMENT '每堂课课时',
  `FINISHED_` tinyint(1) NOT NULL COMMENT '是否结课',
  `COURSE_TYPE` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '课程类型(一对一,一对多)',
  `CREATED_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATED_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID_`) USING BTREE,
  INDEX `TEACHER_ID`(`TEACHER_ID` ASC) USING BTREE,
  CONSTRAINT `MONEYBAG_COURSE_ibfk_1` FOREIGN KEY (`TEACHER_ID`) REFERENCES `MONEYBAG_TEACHER` (`ID_`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '课程表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of MONEYBAG_COURSE
-- ----------------------------

-- ----------------------------
-- Table structure for MONEYBAG_COURSE_HISTORY
-- ----------------------------
DROP TABLE IF EXISTS `MONEYBAG_COURSE_HISTORY`;
CREATE TABLE `MONEYBAG_COURSE_HISTORY`  (
  `ID_` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '历史课程记录ID',
  `COURSE_INSTANCE_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '课程实例ID',
  `ATTENDED_` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否签到',
  `REASON` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '缺课原因',
  `ACTUAL_START_TIME` datetime NOT NULL COMMENT '实际上课开始时间',
  `ACTUAL_END_TIME` datetime NOT NULL COMMENT '实际上课结束时间',
  `CREATED_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATED_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID_`) USING BTREE,
  INDEX `COURSE_INSTANCE_ID`(`COURSE_INSTANCE_ID` ASC) USING BTREE,
  CONSTRAINT `MONEYBAG_COURSE_HISTORY_ibfk_1` FOREIGN KEY (`COURSE_INSTANCE_ID`) REFERENCES `MONEYBAG_COURSE_INSTANCE` (`ID_`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '历史课程记录表' ROW_FORMAT = Dynamic;

