-- ----------------------------

-- ----------------------------
-- Table structure for MONEYBAG_COURSE_INSTANCE
-- ----------------------------
DROP TABLE IF EXISTS `MONEYBAG_COURSE_INSTANCE`;
CREATE TABLE `MONEYBAG_COURSE_INSTANCE`  (
  `ID_` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '课程实例ID',
  `STUDENT_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '学生ID',
  `COURSE_ID` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '课程ID',
  `FEE_` int NOT NULL COMMENT '课时费',
  `CREATED_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATED_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID_`) USING BTREE,
  INDEX `STUDENT_ID`(`STUDENT_ID` ASC) USING BTREE,
  INDEX `COURSE_ID`(`COURSE_ID` ASC) USING BTREE,
  CONSTRAINT `MONEYBAG_COURSE_INSTANCE_ibfk_1` FOREIGN KEY (`STUDENT_ID`) REFERENCES `MONEYBAG_STUDENT` (`ID_`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `MONEYBAG_COURSE_INSTANCE_ibfk_2` FOREIGN KEY (`COURSE_ID`) REFERENCES `MONEYBAG_COURSE` (`ID_`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '课程实例表' ROW_FORMAT = Dynamic;

