  `PARENT_WECHAT_` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '家长微信号',
  `NOTES` varchar(512) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '学生情况备注',
  `CREATED_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATED_AT` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID_`) USING BTREE,
  INDEX `TEACHER_ID`(`TEACHER_ID` ASC) USING BTREE,
  CONSTRAINT `MONEYBAG_STUDENT_ibfk_1` FOREIGN KEY (`TEACHER_ID`) REFERENCES `MONEYBAG_TEACHER` (`ID_`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '学生表' ROW_FORMAT = Dynamic;

